files.inventory.py:
def _chk(stock, qty):
    return stock >= qty


def can_fulfill(stock, qty):
    return _chk(stock, qty)

files.test_inventory.py:
from inventory import can_fulfill


def test_can_fulfill_true_when_enough_stock():
    assert can_fulfill(10, 5) is True


def test_can_fulfill_false_when_not_enough_stock():
    assert can_fulfill(2, 5) is False
